async def act(page):
    """
    Scroll to the bottom of the homepage and navigate to page 5 of the blog feed.

    Strategy:
    - Navigate to the site root ('/') using a relative goto so we are on the homepage.
    - Scroll to the bottom to reveal pagination controls (lazy-loaded or in footer).
    - Prefer semantic navigation region: page.get_by_role("navigation").get_by_role("link", name="5").
    - Fall back to scanning links inside the navigation region for textual variants like "5" or "Page 5".
    - If navigation region isn't present, scan all page links (guarding locator.count()) for the same textual variants.
    - As a last resort, run a DOM query to find an <a> whose visible text matches page-5 patterns and use page.goto(href).

    Notes:
    - All locator.nth()/first() calls are preceded by await locator.count() checks to avoid exceptions.
    - If a click causes navigation, the click is the last action and we return immediately.
    """
    import asyncio

    # 1) Navigate to the site root (use relative path)
    await page.goto('/')

    # 2) Scroll to bottom to reveal pagination; do it a couple times to ensure lazy-loaded content appears
    await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
    await asyncio.sleep(0.8)
    # In some cases doing a small additional scroll helps
    await page.evaluate("window.scrollBy(0, -100)")
    await asyncio.sleep(0.3)
    await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
    await asyncio.sleep(1)

    # helper to click first element of a locator if it exists
    async def try_click_locator(locator):
        if await locator.count() > 0:
            # click the first match and assume navigation may happen
            await locator.first.click()
            return True
        return False

    # 3) Try semantic navigation region first
    nav = page.get_by_role("navigation")
    if await nav.count() > 0:
        # Prefer full path: navigation -> link named "5"
        nav_link5 = nav.get_by_role("link", name="5")
        if await try_click_locator(nav_link5):
            return

        # scan links inside nav for textual variants
        links_inside_nav = nav.get_by_role("link")
        if await links_inside_nav.count() > 0:
            total = await links_inside_nav.count()
            for i in range(total):
                loc = links_inside_nav.nth(i)
                try:
                    txt = (await loc.inner_text() or "").strip()
                except Exception:
                    txt = ""
                lower = txt.lower()
                if txt == "5" or lower == "5" or "page 5" in lower or lower.endswith(" 5") or lower.startswith("5 "):
                    await loc.click()
                    return

    # 4) Try a page-level direct link lookup for '5' as a fallback
    page_link5 = page.get_by_role("link", name="5")
    if await page_link5.count() > 0:
        # If found at page-level, click it
        await page_link5.first.click()
        return

    # 5) Scan all page links for textual variants (guarded by count checks)
    all_links = page.get_by_role("link")
    if await all_links.count() > 0:
        total_links = await all_links.count()
        for i in range(total_links):
            loc = all_links.nth(i)
            try:
                txt = (await loc.inner_text() or "").strip()
            except Exception:
                txt = ""
            lower = txt.lower()
            if txt == "5" or lower == "5" or "page 5" in lower or lower == "page 5":
                await loc.click()
                return

    # 6) Last resort: run a DOM query to find anchors whose visible text matches page-5 patterns
    href = await page.evaluate(r"""() => {
        const anchors = Array.from(document.querySelectorAll('a'));
        for (const a of anchors) {
            const t = (a.textContent || '').trim();
            if (!t) continue;
            if (t === '5' || /page\s*5/i.test(t) || /\b5\b/.test(t)) {
                const h = a.getAttribute('href');
                if (h) return h;
                if (a.href) return a.href;
            }
        }
        return null;
    }""")

    if href:
        # Use relative goto-friendly navigation (page.goto will accept relative or absolute hrefs)
        await page.goto(href)
        return

    # If no page-5 control was found, do nothing further
    return
